import React, { useState, useRef, useEffect } from 'react';
import { useStore } from '../../store/useStore';
import { generateVivaQuestions, gradeVivaAnswer, gradeVivaSession } from '../../utils/aiService';
import { apiPost } from '../../utils/api';

export default function VivaRoom() {
  var store = useStore();
  var [phase, setPhase] = useState('setup');
  var [title, setTitle] = useState('');
  var [topic, setTopic] = useState('');
  var [savedViva, setSavedViva] = useState(null);
  var savedVivaRef = useRef(null);
  var [questions, setQuestions] = useState([]);
  var [currentQ, setCurrentQ] = useState(0);
  var [studentAnswer, setStudentAnswer] = useState('');
  var [examinerNotes, setExaminerNotes] = useState('');
  var [verdict, setVerdict] = useState(null);
  var [transcript, setTranscript] = useState([]);
  var [loading, setLoading] = useState(false);
  var [genTopic, setGenTopic] = useState('');
  var [genCount, setGenCount] = useState(5);
  var [inviteEmail, setInviteEmail] = useState('');
  var [showInvite, setShowInvite] = useState(false);
  var [results, setResults] = useState(null);
  var adminVid = useRef(null);
  var streamRef = useRef(null);

  async function handleStartRoom() {
    if (!title) return;
    setLoading(true);
    try {
      var r = await apiPost('/viva', { title: title, topic: topic, questions: [] });
      var vivaData = { viva_id: r.viva_id, title: title, topic: topic };
      savedVivaRef.current = vivaData;
      setSavedViva(vivaData);
      setPhase('room');
      setTimeout(startMedia, 300);
    } catch (e) { alert(e.message); }
    setLoading(false);
  }

  function startMedia() {
    navigator.mediaDevices.getUserMedia({ video: true, audio: true }).then(function(stream) {
      streamRef.current = stream;
      var attempts = 0;
      var interval = setInterval(function() {
        if (adminVid.current) { adminVid.current.srcObject = stream; clearInterval(interval); }
        attempts++;
        if (attempts > 20) clearInterval(interval);
      }, 200);
    }).catch(function(e) { console.log('Camera error:', e); });
  }

  function stopMedia() {
    if (streamRef.current) { streamRef.current.getTracks().forEach(function(t) { t.stop(); }); }
  }

  async function handleGenerateQ() {
    if (!genTopic) return;
    setLoading(true);
    try {
      var qs = await generateVivaQuestions(genTopic, genCount);
      setQuestions(qs);
      setCurrentQ(0);
    } catch (e) { alert('Generation failed: ' + e.message); }
    setLoading(false);
  }

  async function handleCheckAnswer() {
    if (!studentAnswer || !questions[currentQ]) return;
    setLoading(true);
    try {
      var v = await gradeVivaAnswer(questions[currentQ].question, questions[currentQ].model_answer, studentAnswer);
      setVerdict(v);
    } catch (e) { alert(e.message); }
    setLoading(false);
  }

  function handleSaveNext() {
    var entry = { question: questions[currentQ].question, model_answer: questions[currentQ].model_answer, student_answer: studentAnswer, notes: examinerNotes, verdict: verdict };
    var newT = transcript.concat([entry]);
    setTranscript(newT);
    setStudentAnswer('');
    setExaminerNotes('');
    setVerdict(null);
    if (currentQ < questions.length - 1) { setCurrentQ(currentQ + 1); }
  }

  async function handleEndGrade() {
    stopMedia();
    setLoading(true);
    try {
      var tText = transcript.map(function(t, i) {
        return 'Q' + (i + 1) + ': ' + t.question + '\nStudent: ' + t.student_answer + '\nModel: ' + t.model_answer;
      }).join('\n\n');
      var report = await gradeVivaSession(tText);
      setResults(report);
      var vivaId = savedVivaRef.current ? savedVivaRef.current.viva_id : (savedViva ? savedViva.viva_id : null);
      if (vivaId) {
        await apiPost('/viva/' + vivaId + '/result', { total_score: report.total_score, grade: report.grade, full_transcript: tText, ai_report: report });
      }
      setPhase('results');
    } catch (e) { alert(e.message); }
    setLoading(false);
  }

  async function sendInvites() {
    if (!inviteEmail) return;
    var vivaId = savedVivaRef.current ? savedVivaRef.current.viva_id : (savedViva ? savedViva.viva_id : null);
    if (!vivaId) { alert('Room not created yet'); return; }
    try {
      var emails = inviteEmail.split(',').map(function(e) { return e.trim(); });
      await apiPost('/viva/invite', { emails: emails, title: title, topic: topic, vivaId: vivaId });
      setInviteEmail('');
      setShowInvite(false);
      alert('Invitations sent!');
    } catch (e) { alert(e.message); }
  }

  function copyRoomId() {
    var vivaId = savedVivaRef.current ? savedVivaRef.current.viva_id : '';
    navigator.clipboard.writeText(vivaId);
  }

  // Setup phase
  if (phase === 'setup') {
    return (
      <div className="viva-dark fade-up">
        <div style={{ maxWidth: 500, margin: '60px auto', textAlign: 'center' }}>
          <div style={{ fontSize: '3rem', marginBottom: 16 }}>🎙</div>
          <h2 style={{ color: '#fff', marginBottom: 24 }}>Start Viva Room</h2>
          <div className="card" style={{ textAlign: 'left' }}>
            <div className="form-group"><label className="form-label">Session Title</label><input className="form-input" value={title} onChange={function(e) { setTitle(e.target.value); }} placeholder="e.g. Data Structures Viva" /></div>
            <div className="form-group"><label className="form-label">Topic</label><input className="form-input" value={topic} onChange={function(e) { setTopic(e.target.value); }} placeholder="e.g. Trees and Graphs" /></div>
            <button className="btn btn-primary btn-lg" style={{ width: '100%', justifyContent: 'center' }} onClick={handleStartRoom} disabled={loading || !title}>{loading ? 'Creating...' : '🚀 Start Viva Room'}</button>
          </div>
        </div>
      </div>
    );
  }

  // Results phase
  if (phase === 'results' && results) {
    return (
      <div className="viva-dark fade-up">
        <div style={{ maxWidth: 600, margin: '40px auto', textAlign: 'center' }}>
          <h2 style={{ color: '#fff', marginBottom: 24 }}>📊 Viva Results</h2>
          <div className="card" style={{ padding: 32 }}>
            <div className="score-ring-container">
              <div style={{ fontSize: '3rem', fontWeight: 800, color: 'var(--accent)' }}>{results.total_score}%</div>
              <div style={{ fontSize: '2rem', fontWeight: 700 }}>Grade: {results.grade}</div>
            </div>
            <div style={{ marginTop: 24, textAlign: 'left' }}>
              {results.answers && results.answers.map(function(a, i) {
                return <div key={i} style={{ padding: 12, borderBottom: '1px solid rgba(255,255,255,0.08)' }}>
                  <div style={{ fontWeight: 500 }}>Q{i + 1}: {a.question}</div>
                  <div style={{ fontSize: '0.85rem', color: '#9ca3af', marginTop: 4 }}>{a.feedback}</div>
                  <span className="badge badge-primary" style={{ marginTop: 4 }}>{a.score}%</span>
                </div>;
              })}
            </div>
          </div>
          <button className="btn btn-outline" style={{ marginTop: 20 }} onClick={function() { setPhase('setup'); setResults(null); setTranscript([]); setQuestions([]); }}>🔄 New Session</button>
        </div>
      </div>
    );
  }

  // Room phase
  var vivaId = savedVivaRef.current ? savedVivaRef.current.viva_id : '';

  return (
    <div className="viva-dark fade-up">
      {/* Top bar */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16, flexWrap: 'wrap', gap: 8 }}>
        <div style={{ display: 'flex', gap: 12, alignItems: 'center' }}>
          <span className="badge badge-danger" style={{ animation: 'pulse 2s infinite' }}>🔴 LIVE VIVA</span>
          <span style={{ fontWeight: 600, color: '#fff' }}>{title}</span>
          <span className="badge badge-warning">● REC</span>
        </div>
        <div style={{ display: 'flex', gap: 8 }}>
          <button className="btn btn-sm" style={{ background: 'rgba(255,255,255,0.1)', color: '#e5e5e5' }} onClick={copyRoomId} title="Copy Room ID">🔗 {vivaId.slice(0, 8)}...</button>
          <button className="btn btn-sm btn-outline" onClick={function() { setShowInvite(!showInvite); }}>✉ Invite</button>
          <button className="btn btn-danger btn-sm" onClick={handleEndGrade} disabled={loading}>⏹ End & Grade</button>
        </div>
      </div>

      {showInvite && (
        <div className="card" style={{ marginBottom: 16 }}>
          <div style={{ display: 'flex', gap: 8 }}>
            <input className="form-input" value={inviteEmail} onChange={function(e) { setInviteEmail(e.target.value); }} placeholder="student@email.com (comma-separated)" style={{ flex: 1 }} />
            <button className="btn btn-primary btn-sm" onClick={sendInvites}>Send</button>
          </div>
        </div>
      )}

      {/* 3-column layout */}
      <div className="viva-3col">
        {/* Left */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: 12, overflow: 'auto' }}>
          <div className="card" style={{ padding: 12 }}>
            <video ref={adminVid} autoPlay muted playsInline style={{ width: '100%', borderRadius: 8, background: '#000' }}></video>
            <div style={{ fontSize: '0.75rem', textAlign: 'center', marginTop: 4, color: '#9ca3af' }}>Admin Camera</div>
          </div>
          <div className="card" style={{ padding: 12 }}>
            <div className="form-label">Generate Questions</div>
            <input className="form-input" value={genTopic} onChange={function(e) { setGenTopic(e.target.value); }} placeholder="Topic" style={{ marginBottom: 8 }} />
            <input className="form-input" type="number" value={genCount} onChange={function(e) { setGenCount(Number(e.target.value)); }} min={1} max={20} style={{ marginBottom: 8 }} />
            <button className="btn btn-primary btn-sm" style={{ width: '100%' }} onClick={handleGenerateQ} disabled={loading}>{loading ? '...' : '⚡ Generate'}</button>
          </div>
        </div>

        {/* Middle */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: 12, overflow: 'auto' }}>
          {questions.length > 0 && questions[currentQ] && (
            <div className="card">
              <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 8 }}>
                <span className="badge badge-primary">Q{currentQ + 1}/{questions.length}</span>
              </div>
              <div style={{ fontWeight: 600, fontSize: '1.05rem', marginBottom: 12, color: '#fff' }}>{questions[currentQ].question}</div>
              <div style={{ padding: 10, background: 'rgba(124,58,237,0.1)', borderRadius: 8, fontSize: '0.85rem', color: '#a78bfa', marginBottom: 12 }}>
                <div style={{ fontWeight: 600, fontSize: '0.7rem', marginBottom: 4 }}>MODEL ANSWER (Examiner Only)</div>
                {questions[currentQ].model_answer}
              </div>
              <div className="form-group"><label className="form-label">Student Answer</label><textarea className="form-textarea" value={studentAnswer} onChange={function(e) { setStudentAnswer(e.target.value); }} rows={3} /></div>
              <div className="form-group"><label className="form-label">Examiner Notes</label><textarea className="form-textarea" value={examinerNotes} onChange={function(e) { setExaminerNotes(e.target.value); }} rows={2} /></div>
              {verdict && (
                <div style={{ padding: 12, background: verdict.correct ? 'rgba(22,163,74,0.1)' : 'rgba(220,38,38,0.1)', borderRadius: 8, marginBottom: 12 }}>
                  <div style={{ fontWeight: 600, color: verdict.correct ? '#4ade80' : '#f87171' }}>{verdict.verdict} ({verdict.score_pct}%)</div>
                  <div style={{ fontSize: '0.85rem', marginTop: 4 }}>{verdict.feedback}</div>
                </div>
              )}
              <div style={{ display: 'flex', gap: 8 }}>
                <button className="btn btn-warning btn-sm" onClick={handleCheckAnswer} disabled={loading || !studentAnswer}>⚡ Check</button>
                <button className="btn btn-success btn-sm" onClick={handleSaveNext}>💾 Save & Next</button>
              </div>
            </div>
          )}
          {questions.length === 0 && <div className="card"><div className="empty-state"><div className="empty-state-icon">🎤</div><div className="empty-state-title">Generate questions to begin</div></div></div>}
        </div>

        {/* Right */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: 12, overflow: 'auto' }}>
          <div className="card" style={{ padding: 12 }}>
            <div className="form-label">Questions ({questions.length})</div>
            {questions.map(function(q, i) {
              return <div key={i} onClick={function() { setCurrentQ(i); }} style={{ padding: '8px 10px', borderRadius: 6, cursor: 'pointer', marginBottom: 4, background: i === currentQ ? 'rgba(124,58,237,0.15)' : 'transparent', fontSize: '0.82rem', color: i < transcript.length ? '#4ade80' : '#e5e5e5' }}>
                {i < transcript.length ? '✓ ' : ''}{i + 1}. {q.question.substring(0, 40)}...
              </div>;
            })}
          </div>
          <div className="card" style={{ padding: 12, flex: 1 }}>
            <div className="form-label">Transcript ({transcript.length})</div>
            {transcript.map(function(t, i) {
              return <div key={i} style={{ padding: 8, borderBottom: '1px solid rgba(255,255,255,0.05)', fontSize: '0.8rem' }}>
                <div style={{ fontWeight: 500 }}>Q{i + 1}: {t.question.substring(0, 50)}...</div>
                <div style={{ color: '#9ca3af' }}>A: {t.student_answer.substring(0, 60)}...</div>
              </div>;
            })}
          </div>
        </div>
      </div>
    </div>
  );
}
